<?php $title = 'حواله خروج ' . $issue['issue_code']; $statusLabels = ['pending' => 'در انتظار بررسی', 'approved' => 'تأیید خروج', 'rejected' => 'رد شده']; ?>
<div class="card issue-status issue-<?= e($issue['status']) ?>"><div class="issue-card-head"><h2><?= e($issue['issue_code']) ?></h2><span class="badge <?= $issue['status'] === 'approved' ? 'ok' : ($issue['status'] === 'rejected' ? 'danger' : 'warn') ?>"><?= e($statusLabels[$issue['status']]) ?></span></div><div class="grid"><p class="col-4"><strong>درخواست‌دهنده:</strong> <?= e($issue['requester_name']) ?></p><p class="col-4"><strong>انبار:</strong> <?= e($issue['warehouse_name']) ?></p><p class="col-4"><strong>تحویل‌گیرنده:</strong> <?= e($issue['recipient_name'] ?: '-') ?></p></div><p><strong>توضیحات:</strong> <?= nl2br(e($issue['notes'] ?: '-')) ?></p><?php if ($issue['status'] !== 'pending'): ?><p><strong><?= $issue['status'] === 'approved' ? 'تأییدکننده' : 'ردکننده' ?>:</strong> <?= e($issue['reviewer_name']) ?> · <?= e(jalali_like_datetime($issue['reviewed_at'])) ?></p><p><strong>توضیحات بررسی:</strong> <?= nl2br(e($issue['review_notes'] ?: '-')) ?></p><?php endif; ?></div>
<div class="card"><h2>اقلام حواله</h2><div class="table-wrap"><table class="table"><tr><th>تصویر</th><th>کالا</th><th>کد کالا</th><th>مقدار</th><th>توضیحات</th></tr><?php foreach ($issue['items'] as $item): ?><tr><td><?php if ($item['image_path']): ?><img class="item-thumbnail" src="<?= e(item_image_url($item['image_path'])) ?>" alt="<?= e($item['item_name']) ?>"><?php endif; ?></td><td><?= e($item['item_name']) ?></td><td><?= e($item['sku']) ?></td><td><?= e(moneyless_number($item['quantity'])) ?> <?= e($item['unit_symbol']) ?></td><td><?= e($item['notes'] ?: '-') ?></td></tr><?php endforeach; ?></table></div></div>
<div class="actions no-print"><a class="btn light" target="_blank" href="<?= e(base_url('issue-requests/print?id=' . $issue['id'])) ?>">چاپ حواله</a><a class="btn light" href="<?= e(base_url('issue-requests')) ?>">بازگشت به آرشیو</a></div>
<?php if ($issue['status'] === 'pending' && can('issue_review')): ?><div class="card"><h2>بررسی انباردار</h2><form method="post" action="<?= e(base_url('issue-requests/review')) ?>"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($issue['id']) ?>"><label>توضیحات بررسی <span class="muted">(برای رد الزامی است)</span></label><textarea name="review_notes" data-review-notes></textarea><div class="actions"><button class="btn" name="action" value="approve">تأیید خروج از انبار</button><button class="btn danger" name="action" value="reject" data-reject-issue>رد حواله</button></div></form></div><?php endif; ?>
